 152	const blockKey = (folioId: string, blockId: string) => `tw:draft:${folioId}:block:${blockId}`;
 153	const orderKey = (folioId: string) => `tw:draft:${folioId}:order`;
 154	
 155	/**
 156	 * Split manuscript html into top-level blocks. Block ids are positional
 157	 * (`b0`, `b1`, …) and re-derived on every mirror; proposals reference a block
 158	 * by id captured at propose time, which is stable for the short window
 159	 * between proposing and accepting/striking.
 160	 */
 161	export function splitBlocks(html: string): DraftBlock[] {
 162	  if (typeof window === "undefined") return [];
 163	  const doc = new DOMParser().parseFromString(html, "text/html");
 164	  return Array.from(doc.body.children).map((el, i) => ({
 165	    id: `b${i}`,
 166	    html: el.outerHTML,
 167	  }));
 168	}
