 170	/**
 171	 * What we last wrote to Lix, per folio: block id → html, plus the serialized
 172	 * order. Lets a mirror skip blocks the writer did not touch.
 173	 *
 174	 * Safe for the lifetime of the tab because `getLix()` memoizes a single
 175	 * instance that is never torn down. If a remote change-set overwrites a block
 176	 * underneath us, the local html is by definition unchanged too, so skipping
 177	 * the write is the correct outcome — the remote value wins, which is the
 178	 * point of pulling it.
 179	 */
 180	const mirroredBlocks = new Map<string, Map<string, string>>();
 181	const mirroredOrder = new Map<string, string>();
 182	
 183	/**
 184	 * Mirror the live manuscript into Lix key_value entries on the current
 185	 * version, writing only what actually moved.
 186	 *
 187	 * This used to `await` a SELECT-then-UPDATE per top-level block, in sequence.
 188	 * Lix is SQLite compiled to WASM running on the main thread, and the JSON
 189	 * change-control plugin records a change row per write — so a 300-paragraph
 190	 * manuscript cost 600 serialized statements and 300 change records on every
 191	 * autosave. `await` yielded to the microtask queue between them but the CPU
 192	 * work stayed on the main thread, which is what made typing stutter after a
 193	 * pause. Now it is one DELETE plus one batched INSERT covering only the
 194	 * changed blocks, and it returns without touching the database at all when
 195	 * nothing changed.
 196	 */
 197	export async function syncDraftToLix(folioId: string, html: string): Promise<void> {
 198	  if (!folioId) return;
 199	  const blocks = splitBlocks(html);
 200	  const next = new Map(blocks.map((b) => [b.id, b.html]));
 201	  const previous = mirroredBlocks.get(folioId);
 202	  const order = JSON.stringify(blocks.map((b) => b.id));
 203	
 204	  const changed = previous
 205	    ? blocks.filter((b) => previous.get(b.id) !== b.html)
 206	    : blocks;
 207	  const removed = previous
 208	    ? [...previous.keys()].filter((id) => !next.has(id))
 209	    : [];
 210	  const orderChanged = mirroredOrder.get(folioId) !== order;
 211	
 212	  if (!changed.length && !removed.length && !orderChanged) return;
 213	
 214	  const lix = await getLix();
 215	  const staleKeys = [
 216	    ...changed.map((b) => blockKey(folioId, b.id)),
 217	    ...removed.map((id) => blockKey(folioId, id)),
 218	    ...(orderChanged ? [orderKey(folioId)] : []),
 219	  ];
 220	  await lix.db.deleteFrom("key_value").where("key", "in", staleKeys).execute();
 221	
 222	  const rows = [
 223	    ...changed.map((b) => ({ key: blockKey(folioId, b.id), value: b.html })),
 224	    ...(orderChanged ? [{ key: orderKey(folioId), value: order }] : []),
 225	  ];
 226	  if (rows.length) {
 227	    await lix.db.insertInto("key_value").values(rows).execute();
 228	  }
 229	
 230	  mirroredBlocks.set(folioId, next);
 231	  mirroredOrder.set(folioId, order);
 232	  markDirty();
 233	}
