 235	export async function getDraftBlocks(folioId: string): Promise<DraftBlock[]> {
 236	  const order = await kvGet(orderKey(folioId));
 237	  if (!order) return [];
 238	  const ids = JSON.parse(order) as string[];
 239	  const blocks: DraftBlock[] = [];
 240	  for (const id of ids) {
 241	    const html = await kvGet(blockKey(folioId, id));
 242	    if (html != null) blocks.push({ id, html });
 243	  }
 244	  return blocks;
 245	}
