 153	/* ────────────────────────────────────────────────────────────────
 154	 *  Editorial dateline — formatted like a print magazine masthead.
 155	 *  e.g. "Vol. I · No. 117 · Sunday, the 26th of April, 2026"
 156	 * ──────────────────────────────────────────────────────────────── */
 157	function editorialDateline(now = new Date()): string {
 158	  const days = [
 159	    "Sunday",
 160	    "Monday",
 161	    "Tuesday",
 162	    "Wednesday",
 163	    "Thursday",
 164	    "Friday",
 165	    "Saturday",
 166	  ];
 167	  const months = [
 168	    "January",
 169	    "February",
 170	    "March",
 171	    "April",
 172	    "May",
 173	    "June",
 174	    "July",
 175	    "August",
 176	    "September",
 177	    "October",
 178	    "November",
 179	    "December",
 180	  ];
 181	  const day = now.getDate();
 182	  const ordinal = (n: number) => {
 183	    const s = ["th", "st", "nd", "rd"];
 184	    const v = n % 100;
 185	    return n + (s[(v - 20) % 10] || s[v] || s[0]);
 186	  };
 187	  const start = new Date(now.getFullYear(), 0, 0);
 188	  const diff = (now.getTime() - start.getTime()) / 86400000;
 189	  const dayOfYear = Math.floor(diff);
 190	  return `Vol. I · No. ${dayOfYear} · ${days[now.getDay()]}, the ${ordinal(day)} of ${months[now.getMonth()]}, ${now.getFullYear()}`;
 191	}
