109	 * sound like genuinely different people rather than one writer in five hats.
110	 * Falls back to nothing when a persona has no voice spec (older saved casts).
111	 */
112	function buildVoiceBlock(persona: AgentPersona): string {
113	  if (
114	    !persona.backstory &&
115	    !persona.criticalMethod &&
116	    !persona.voice &&
117	    (!persona.signatureMoves || persona.signatureMoves.length === 0) &&
118	    (!persona.avoidances || persona.avoidances.length === 0) &&
119	    (!persona.sampleLines || persona.sampleLines.length === 0)
120	  ) {
121	    return "\nSpeak in your own voice. Do not sound like the other editors.\n";
122	  }
123	  const lines: string[] = [
124	    "\nPERSONA BIBLE (binding for every note, reply, rewrite, analysis, and judgment):",
125	  ];
126	  if (persona.backstory) {
127	    lines.push(
128	      `BACKSTORY (internalize it; mention it only when it naturally matters):\n${persona.backstory}`,
129	    );
130	  }
131	  if (persona.criticalMethod) {
132	    lines.push(`EDITORIAL DOCTRINE:\n${persona.criticalMethod}`);
133	  }
134	  if (persona.voice) lines.push(`VOICEPRINT:\n${persona.voice}`);
135	  if (persona.signatureMoves && persona.signatureMoves.length > 0) {
136	    lines.push(
137	      `SIGNATURE MOVES (use one or two when natural, not all mechanically):\n${persona.signatureMoves
138	        .map((move) => `- ${move}`)
139	        .join("\n")}`,
140	    );
141	  }
142	  if (persona.avoidances && persona.avoidances.length > 0) {
143	    lines.push(
144	      `NEVER BORROW THESE HABITS:\n${persona.avoidances
145	        .map((avoidance) => `- ${avoidance}`)
146	        .join("\n")}`,
147	    );
148	  }
149	  if (persona.sampleLines && persona.sampleLines.length > 0) {
150	    lines.push(
151	      `Lines in your register, for calibration (do not reuse them verbatim):\n${persona.sampleLines
152	        .map((l) => `  — ${l}`)
