231	  | { kind: "offline" } // navigator says we're offline
232	  | { kind: "pending"; queuedAt: number } // a push is scheduled
233	  | { kind: "syncing" } // a push is in flight
234	  | { kind: "synced"; lastSyncedAt: number }
235	  | { kind: "error"; lastErrorAt: number; message: string };
