237	export function getSyncStatus(): SyncStatus {
238	  if (!state.userId) return { kind: "local-only" };
239	  if (typeof navigator !== "undefined" && !navigator.onLine) {
240	    return { kind: "offline" };
241	  }
242	  if (state.pushing) return { kind: "syncing" };
243	  if (pushTimer) return { kind: "pending", queuedAt: Date.now() };
244	  if (
245	    state.lastErrorAt &&
246	    (!state.lastSyncedAt || state.lastErrorAt > state.lastSyncedAt)
247	  ) {
248	    return {
249	      kind: "error",
250	      lastErrorAt: state.lastErrorAt,
251	      message:
252	        state.lastErrorMessage ??
