640	/** Rows whose content differs from the last acknowledged push. */
641	function changedRows<T>(
642	  next: T[],
643	  previous: T[] | undefined,
644	  identify: (row: T) => string,
645	): T[] {
646	  if (!previous) return next;
647	  const before = new Map(
648	    previous.map((row) => [identify(row), serialize(row)]),
649	  );
650	  return next.filter((row) => before.get(identify(row)) !== serialize(row));
651	}
