653	/**
654	 * Rows present in the last acknowledged push but missing from the next
655	 * snapshot. These were deleted locally and have to be told to leave the server
656	 * too — a section that only ever upserts would otherwise keep them forever.
657	 */
658	function removedRows<T>(
659	  next: T[],
660	  previous: T[] | undefined,
661	  identify: (row: T) => string,
662	): string[] {
663	  if (!previous) return [];
664	  const keys = new Set(next.map(identify));
665	  return previous
666	    .filter((row) => !keys.has(identify(row)))
667	    .map((row) => identify(row));
668	}
