782	  // diff against the same `state.lastPushed`, with whichever mutation resolved
783	  // last winning the write-back. A slow earlier push could then re-ratify a
784	  // payload a later push had already superseded, and every subsequent diff
785	  // would consider the difference already sent. Queue instead.
786	  if (state.pushing) {
787	    pushAgainWhenDone = true;
788	    return;
789	  }
790	  state.pushing = true;
791	  notifyStatusChange();
792	  const dirty = state.dirtySections;
793	  state.dirtySections = new Set<PushSection>();
794	  try {
795	    // Rebuild only the sections that moved since the last push. The diff
796	    // against `lastPushed` is still against the full payload, so a clean
797	    // section reports "unchanged" and gets skipped on the wire.
798	    const snapshot = await buildLocalSnapshot(dirty);
799	    const payload = buildPushPayload(snapshot);
800	    const changes = diffPushPayload(payload, state.lastPushed);
801	    if (changes) {
802	      await state.client.mutation(api.sync.pushAll, changes);
803	      // Only now is the server known to hold this. A push that threw leaves
804	      // `lastPushed` where it was, so the next one carries the whole gap.
805	      state.lastPushed = payload;
806	    }
807	    state.lastSnapshot = snapshot;
808	    // Success: clear the error and stamp the synced time.
809	    state.lastSyncedAt = Date.now();
810	    state.lastErrorAt = null;
811	    state.lastErrorMessage = null;
812	  } catch (err) {
813	    // The snapshots may not have reached the server — keep those sections
814	    // dirty so the next push rebuilds rather than skips exactly them.
815	    if (dirty) {
816	      for (const section of dirty) state.dirtySections.add(section);
817	    }
818	    setSyncFailure(err, "push-all");
819	  } finally {
820	    state.pushing = false;
821	    notifyStatusChange();
822	    if (pushAgainWhenDone) {
823	      pushAgainWhenDone = false;
824	      void pushLocalSnapshot();
825	    }
