  args: { lixId: v.string(), userId: v.string() },
  handler: async (ctx, { lixId, userId }) => {
    const row = await getCollaborator(ctx, lixId, userId);
    if (!row || row.status !== "accepted") return null;
    return row.role as "owner" | "editor" | "commenter";
  },
});
